import numpy as np
import pytest
import media_utils


def _make_video_frames(num_frames=4, height=8, width=8):
    return np.random.randint(
        0, 256, size=(num_frames, height, width, 3), dtype=np.uint8
    )


def test_mux_valid_video_only():
    """Video-only muxing (no audio) should work and return non-empty bytes."""
    frames = _make_video_frames()
    result = media_utils.mux_video_audio_bytes(frames, fps=25.0)
    assert isinstance(result, bytes)
    assert len(result) > 0
